import { readFileSync } from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

test.describe("upload vendor documents", () => {
  test("documents from another tenant are invisible", { tag: "@DOC-07" }, async ({ apiAs }) => {
    // Arrange: a Globex vendor with a document, created as a Globex member
    const globex = await apiAs("otherTenant");
    const vendorRes = await globex.post("/api/vendors", {
      data: {
        name: uniqueName("Globex Vendor"),
        category: "services",
        contact_email: `ops+${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@example.com`,
      },
    });
    expect(vendorRes.status(), await vendorRes.text()).toBe(201);
    const vendor = await vendorRes.json();

    const uploadRes = await globex.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "w9",
        file: {
          name: "w9.txt",
          mimeType: "text/plain",
          buffer: readFileSync(sample("w9.txt")),
        },
      },
    });
    expect(uploadRes.status(), await uploadRes.text()).toBe(201);
    const document = await uploadRes.json();

    // Arrange: a Northwind member with a draft vendor of their own
    const member = await apiAs("member");
    const ownVendorRes = await member.post("/api/vendors", {
      data: {
        name: uniqueName("Northwind Vendor"),
        category: "hardware",
        contact_email: `ops+${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@example.com`,
      },
    });
    expect(ownVendorRes.status(), await ownVendorRes.text()).toBe(201);
    expect((await ownVendorRes.json()).status).toBe("draft");

    // Act: request the Globex document by id as the Northwind member
    const response = await member.get(`/api/documents/${document.id}`);

    // Assert
    expect(response.status(), await response.text()).toBe(404);
    const body = await response.json();
    expect(body.error.code, JSON.stringify(body)).toBe("document_not_found");
  });
});
